/bin/bash -lc "python3 - <<'PY'
import zipfile, xml.etree.ElementTree as ET
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
with zipfile.ZipFile('/home/user/Name_Order_Id_move_column.xlsx') as z:
 root=ET.fromstring(z.read('xl/styles.xml'))
 numfmts={}
 nfroot=root.find('m:numFmts',ns)
 if nfroot is not None:
  for nf in nfroot.findall('m:numFmt',ns): numfmts[nf.attrib['numFmtId']]=nf.attrib['formatCode']
 print('custom numFmts',numfmts)
 for i,xf in enumerate(root.find('m:cellXfs',ns).findall('m:xf',ns)):
  print(i, xf.attrib, numfmts.get(xf.attrib.get('numFmtId'), 'builtin'))
PY"

